// Code generated by scripts/generate_graph_identifier_policy.py from
// specs/graph_identifier_policy.json; DO NOT EDIT.

pub const GRAPH_IDENTIFIER_POLICY_VERSION: u32 = 1;
pub const GRAPH_IDENTIFIER_UNICODE_VERSION: &str = "15.0.0";
pub const MAX_GRAPH_IDENTIFIER_CODE_POINTS: usize = 128;
pub const MAX_GRAPH_IDENTIFIER_UTF8_BYTES: usize = 512;

const DISALLOWED_RANGES: &[(u32, u32)] = &[
    (0x0, 0x1F),
    (0x7F, 0xA0),
    (0xAD, 0xAD),
    (0x600, 0x605),
    (0x61C, 0x61C),
    (0x6DD, 0x6DD),
    (0x70F, 0x70F),
    (0x890, 0x891),
    (0x8E2, 0x8E2),
    (0x1680, 0x1680),
    (0x180E, 0x180E),
    (0x2000, 0x200F),
    (0x2028, 0x202F),
    (0x205F, 0x2064),
    (0x2066, 0x206F),
    (0x3000, 0x3000),
    (0xD800, 0xDFFF),
    (0xFEFF, 0xFEFF),
    (0xFFF9, 0xFFFB),
    (0x110BD, 0x110BD),
    (0x110CD, 0x110CD),
    (0x13430, 0x1343F),
    (0x1BCA0, 0x1BCA3),
    (0x1D173, 0x1D17A),
    (0xE0001, 0xE0001),
    (0xE0020, 0xE007F),
];
const RESERVED_EXACT: &[&str] = &["*"];
const RESERVED_PREFIXES: &[&str] = &["$"];

fn code_point_disallowed(code_point: u32) -> bool {
    DISALLOWED_RANGES
        .binary_search_by(|(lo, hi)| {
            if code_point < *lo {
                std::cmp::Ordering::Greater
            } else if code_point > *hi {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// Return whether `value` satisfies the versioned Antfly wire policy.
pub fn is_valid_graph_identifier(value: &str) -> bool {
    if value.is_empty()
        || value.len() > MAX_GRAPH_IDENTIFIER_UTF8_BYTES
        || RESERVED_EXACT.contains(&value)
        || RESERVED_PREFIXES
            .iter()
            .any(|prefix| value.starts_with(prefix))
    {
        return false;
    }

    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if first == ' ' || code_point_disallowed(first as u32) {
        return false;
    }
    let mut count = 1;
    let mut last = first;
    for code_point in chars {
        count += 1;
        last = code_point;
        if count > MAX_GRAPH_IDENTIFIER_CODE_POINTS || code_point_disallowed(code_point as u32) {
            return false;
        }
    }
    last != ' '
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_versioned_wire_policy_conformance_cases() {
        let cases = [
            ("ascii", "author", true),
            ("internal_ascii_space", "post author", true),
            ("visible_unicode", "\u{6587}\u{7ae0}", true),
            ("decomposed_unicode", "e\u{301}", true),
            ("empty", "", false),
            ("count_sentinel", "*", false),
            ("reserved_prefix", "$result", false),
            ("leading_space", " author", false),
            ("trailing_space", "author ", false),
            ("newline", "post\nauthor", false),
            ("null_control", "post\0author", false),
            ("non_breaking_space", "post\u{a0}author", false),
            ("zero_width_space", "post\u{200b}author", false),
            ("line_separator", "post\u{2028}author", false),
            ("bidi_override", "post\u{202e}author", false),
        ];
        for (name, value, valid) in cases {
            assert_eq!(is_valid_graph_identifier(value), valid, "{name}");
        }
    }
}
